#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int E, M, D;
    if (scanf("%d %d %d", &E, &M, &D) != 3) return 0;

    int *lx = NULL, *ly = NULL, *dx = NULL, *dy = NULL;

    if (M > 0) {
        lx = (int *)malloc(sizeof(int) * M);
        ly = (int *)malloc(sizeof(int) * M);
    }
    for (int i = 0; i < M; ++i) {
        scanf("%d %d", &lx[i], &ly[i]);
    }

    if (D > 0) {
        dx = (int *)malloc(sizeof(int) * D);
        dy = (int *)malloc(sizeof(int) * D);
    }
    for (int i = 0; i < D; ++i) {
        scanf("%d %d", &dx[i], &dy[i]);
    }

    int *grp = (int *)malloc(sizeof(int) * (E + 1));
    int groups = E / 3;

    for (int i = 0; i < groups; ++i) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        grp[a] = i;
        grp[b] = i;
        grp[c] = i;
    }

    int ans = 0;

    for (int i = 0; i < M; ++i) {
        if (grp[lx[i]] != grp[ly[i]]) {
            ++ans;
        }
    }

    for (int i = 0; i < D; ++i) {
        if (grp[dx[i]] == grp[dy[i]]) {
            ++ans;
        }
    }

    printf("%d\n", ans);

    free(lx);
    free(ly);
    free(dx);
    free(dy);
    free(grp);

    return 0;
}
